def pre(x):
    return And(x >= 1, x <= 50)

def post(x, r):
    # Symbols contributed by the units digit (0..9): I, II, III, IV, V, VI, VII, VIII, IX
    u = [0, 1, 2, 3, 2, 1, 2, 3, 4, 2]
    # Symbols contributed by the tens digit (0..5): X, XX, XXX, XL, L
    t = [0, 1, 2, 3, 2, 1]
    cases = []
    for v in range(1, 51):
        cases.append(And(x == v, r == t[v // 10] + u[v % 10]))
    return Or(*cases)
